"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["78105"],{11314(e,t,n){n.r(t),n.d(t,{metadata:()=>r,default:()=>l,frontMatter:()=>p,contentTitle:()=>c,toc:()=>h,assets:()=>d});var r=JSON.parse('{"id":"nhcx/v1/api/registry/endpoints/registry-product-getowner","title":"Get product owner","description":"Resolves a product ID to the participant code of the payer that owns it.","source":"@site/docs/nhcx/v1/api/registry/endpoints/registry-product-getowner.mdx","sourceDirName":"nhcx/v1/api/registry/endpoints","slug":"/nhcx/v1/api/registry/endpoints/registry-product-getowner","permalink":"/docs/pr-30/docs/nhcx/v1/api/registry/endpoints/registry-product-getowner","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Get product owner","sidebar_label":"Get product owner","sidebar_class_name":"api-method api-method--post","description":"Resolves a product ID to the participant code of the payer that owns it.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-registry.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Submit the de-link payer product","permalink":"/docs/pr-30/docs/nhcx/v1/api/registry/endpoints/registry-product-delink"},"next":{"title":"Get product ID and name","permalink":"/docs/pr-30/docs/nhcx/v1/api/registry/endpoints/registry-participant-getproductidname"}}'),a=n(62540),i=n(43023),o=n(85030),s=JSON.parse('{"id":"registry_product_getowner","module":"Participant registry","moduleId":"registry","kind":"operation","method":"POST","path":"/product/getowner","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Get product owner","title":"Get product owner","description":"Resolves a product ID to the participant code of the payer that owns it.\\n\\n### Business purpose\\n\\nGiven only a product identifier, an integrator often needs to know which payer stands behind it. This Retrieving API call takes a ProductOwnerRequest with productid and returns ParticipantCreateResponse, whose participant_code is the owning participant\'s identifier on the HCX instance. That makes it a useful bridge between a product seen on a policy document or in a policy lookup and the participant code that must go into routing. Note that the OpenAPI description reads \\"This API is to generate the product ID and product Name\\", which does not match the response schema; the source does not resolve this conflict.\\n\\n### When to use\\n\\nUse it when you have a product ID and need the payer that owns it.\\n\\n### Preconditions\\n\\n- You have a valid access token in the `bearer_auth` header.\\n- You send the `productid`.\\n- The payer has registered the product.\\n\\n### Postconditions\\n\\nYou get the owning payer\'s participant code. Nothing changes.\\n\\n### Common mistakes\\n\\n- Using this code as `x-hcx-recipient_code` when a TPA processes the payer\'s claims. Use the processing ID from get-policies.\\n- Expecting product details in the answer.\\n- Sending an empty body.\\n\\n### Best practices\\n\\n- Treat the result as the product owner (payerid), then resolve the effective receiver through the policy lookup.\\n- Cache owner lookups by productid; ownership changes rarely and only through /product/link and /product/delink.\\n- Handle a missing participant_code gracefully; every field in the response is optional.\\n- Refresh the Bearer token proactively and retry once on 401.\\n\\n### Related scenario\\n\\nA hospital receives a scanned policy card that shows only a product ID, and the patient\'s ABHA-based policy lookup returned more than one payer. The HMIS calls /product/getowner with the product ID and gets back the participant code of the insurer that owns it, which lets the desk pick the right entry from the /participant/get/policies result. With the matched policy in hand the system reads the processingID as the receiver code, requests the plan through /v1/insuranceplan/request and goes on to submit the preauthorisation.\\n\\n### Specification\\n\\nChapter [Participants and policies](/docs/nhcx/v1/registries) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"productid","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"productid":"PRD-FLOATER-01"},"responses":[{"status":"200","description":"Returns HTTP 200 with ParticipantCreateResponse containing the optional participant_code of the owning participant.","example":{"participant_code":"100234@sbx"}}],"curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/product/getowner \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"productid\\": \\"PRD-FLOATER-01\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/product/getowner \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"productid\\": \\"PRD-FLOATER-01\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/product/getowner\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"productid\\": \\"PRD-FLOATER-01\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node.js","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/product/getowner\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"productid\\": \\"PRD-FLOATER-01\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"},{"id":"java","label":"Java","language":"java","code":"import java.net.URI;\\nimport java.net.http.HttpClient;\\nimport java.net.http.HttpRequest;\\nimport java.net.http.HttpResponse;\\n\\nHttpClient client = HttpClient.newHttpClient();\\nHttpRequest request = HttpRequest.newBuilder()\\n    .uri(URI.create(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/product/getowner\\"))\\n    .header(\\"Authorization\\", \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\")\\n    .header(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n    .header(\\"Content-Type\\", \\"application/json\\")\\n    .method(\\"POST\\", HttpRequest.BodyPublishers.ofString(\\"\\"\\"\\n        {\\n            \\"productid\\": \\"PRD-FLOATER-01\\"\\n        }\\n        \\"\\"\\"))\\n    .build();\\n\\nHttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());\\nSystem.out.println(response.statusCode() + \\" \\" + response.body());"},{"id":"php","label":"PHP","language":"php","code":"<?php\\n\\n$ch = curl_init(\'https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/product/getowner\');\\ncurl_setopt_array($ch, [\\n    CURLOPT_CUSTOMREQUEST => \'POST\',\\n    CURLOPT_RETURNTRANSFER => true,\\n    CURLOPT_HTTPHEADER => [\\n        \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\',\\n        \'bearer_auth: Bearer <access token>\',\\n        \'Content-Type: application/json\',\\n    ],\\n    CURLOPT_POSTFIELDS => <<<\'JSON\'\\n    {\\n        \\"productid\\": \\"PRD-FLOATER-01\\"\\n    }\\n    JSON,\\n]);\\n\\n$response = curl_exec($ch);\\necho curl_getinfo($ch, CURLINFO_HTTP_CODE), \' \', $response, PHP_EOL;"},{"id":"go","label":"Go","language":"go","code":"package main\\n\\nimport (\\n\\t\\"fmt\\"\\n\\t\\"io\\"\\n\\t\\"net/http\\"\\n\\t\\"strings\\"\\n)\\n\\nfunc main() {\\n\\tbody := strings.NewReader(`{\\n  \\"productid\\": \\"PRD-FLOATER-01\\"\\n}`)\\n\\treq, err := http.NewRequest(\\"POST\\", \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/product/getowner\\", body)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\treq.Header.Set(\\"Authorization\\", \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\")\\n\\treq.Header.Set(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n\\treq.Header.Set(\\"Content-Type\\", \\"application/json\\")\\n\\n\\tresp, err := http.DefaultClient.Do(req)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\tdefer resp.Body.Close()\\n\\tout, _ := io.ReadAll(resp.Body)\\n\\tfmt.Println(resp.StatusCode, string(out))\\n}"},{"id":"csharp","label":"C#","language":"csharp","code":"using var client = new HttpClient();\\nvar request = new HttpRequestMessage(new HttpMethod(\\"POST\\"), \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/product/getowner\\");\\nrequest.Headers.TryAddWithoutValidation(\\"Authorization\\", \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\");\\nrequest.Headers.TryAddWithoutValidation(\\"bearer_auth\\", \\"Bearer <access token>\\");\\nrequest.Content = new StringContent(\\"\\"\\"\\n    {\\n        \\"productid\\": \\"PRD-FLOATER-01\\"\\n    }\\n    \\"\\"\\", System.Text.Encoding.UTF8, \\"application/json\\");\\n\\nvar response = await client.SendAsync(request);\\nConsole.WriteLine($\\"{(int)response.StatusCode} {await response.Content.ReadAsStringAsync()}\\");"},{"id":"ruby","label":"Ruby","language":"ruby","code":"require \'net/http\'\\n\\nuri = URI(\'https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/product/getowner\')\\nrequest = Net::HTTP::Post.new(uri)\\nrequest[\'Authorization\'] = \'Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\'\\nrequest[\'bearer_auth\'] = \'Bearer <access token>\'\\nrequest[\'Content-Type\'] = \'application/json\'\\nrequest.body = <<~\'JSON\'\\n  {\\n    \\"productid\\": \\"PRD-FLOATER-01\\"\\n  }\\nJSON\\n\\nresponse = Net::HTTP.start(uri.hostname, uri.port, use_ssl: uri.scheme == \'https\') do |http|\\n  http.request(request)\\nend\\nputs response.code, response.body"}]}');let p={title:"Get product owner",sidebar_label:"Get product owner",sidebar_class_name:"api-method api-method--post",description:"Resolves a product ID to the participant code of the payer that owns it.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-registry.yaml",generated:!0},c,d={},h=[];function u(e){return(0,a.jsx)(o.A,{operation:s})}function l(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(u,{...e})}):u(e)}}}]);